<template>
  <DewCard v-if="enabled" no-hover class="composition-panel"><header><h3>独立项目参营</h3><DewButton size="sm" @click="load">刷新</DewButton></header><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!rows.length">暂无独立项目关联。</p><article v-for="row in rows" :key="row.binding.id"><h4>{{ row.project.title }} · {{ row.project.code }} · {{ labels[row.binding.status] }}</h4><p>{{ (row.binding.requested_users.length ? row.binding.requested_users : row.binding.participants).map(m=>m.name).join('、') }}</p><div class="composition-actions"><template v-if="writable"><DewButton v-if="row.binding.status==='requested'" size="sm" @click="act(row,'approve')">批准参营</DewButton><DewButton v-if="row.binding.status==='requested'" size="sm" type="ghost" @click="act(row,'reject')">拒绝</DewButton><DewButton v-if="row.binding.change_pending" size="sm" @click="act(row,'participants')">确认名单变更</DewButton><DewButton v-if="row.binding.status==='active'" size="sm" type="ghost" @click="openLeader(row)">交接本期负责人</DewButton><DewButton v-if="row.binding.status==='active'" size="sm" type="ghost" @click="act(row,'end')">结束本期关联</DewButton></template><DewButton size="sm" type="ghost" @click="openProject(row)">用户端本期视图</DewButton></div></article><DewDialog v-model="dialog" title="交接本期负责人" width="480px"><DewSelect v-model="leaderId" :options="(selected?.binding.participants||[]).map(m=>({value:m.user_id,label:m.name}))" /><template #footer><DewButton @click="act(selected,'participants',leaderId)">确认交接</DewButton></template></DewDialog></DewCard>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {DewCard,DewButton,DewSelect,DewDialog} from '@bme/dew-ui'
import api from '../../../api'
const props=defineProps({sid:[String,Number],writable:Boolean}),emit=defineEmits(['changed'])
const enabled=ref(false),rows=ref([]),error=ref(''),busy=ref(false),dialog=ref(false),selected=ref(null),leaderId=ref(null)
const labels={requested:'待审批',active:'参营中',ended:'已结束',rejected:'未通过'};let sequence=0
async function load(){const seq=++sequence;error.value='';try{if(!(await api.get('/project-core/status')).data.enabled)return;enabled.value=true;const d=await api.get(`/project-core/camps/${props.sid}/projects`);if(seq===sequence)rows.value=d.data.projects}catch(e){if(seq===sequence&&enabled.value)error.value=e.response?.data?.message||'项目关联加载失败'}}
async function act(row,action,leader){if(busy.value||!props.writable)return;let reason;try{reason=(await ElMessageBox.prompt('填写处理依据','项目参营',{inputValidator:v=>!!v?.trim()||'请填写原因'})).value}catch{return}busy.value=true;try{await api.post(`/project-core/projects/${row.project.id}/camps/${row.binding.id}`,{action,reason,expected_version:row.project.version,expected_binding_version:row.binding.version,idempotency_key:crypto.randomUUID(),user_ids:action==='participants'?(row.binding.change_pending&&!leader?row.binding.requested_users:row.binding.participants).map(m=>m.user_id):undefined,leader_user_id:leader||undefined});dialog.value=false;await load();emit('changed');ElMessage.success('本期关联已更新')}catch(e){ElMessage.error(e.response?.data?.message||'操作失败')}finally{busy.value=false}}
function openLeader(row){selected.value=row;leaderId.value=row.binding.leader_user_id;dialog.value=true}
function openProject(row){window.open(`/AMEII/project-workspace/${row.project.id}?binding=${row.binding.id}&view=camp&tab=assessment&unit=${row.binding.unit_id||''}`,'_blank','noopener')}
watch(()=>props.sid,()=>{enabled.value=false;rows.value=[];dialog.value=false;load()},{immediate:true});onBeforeUnmount(()=>sequence++)
</script>
<style scoped>.composition-panel{margin-bottom:22px}.composition-panel header,.composition-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.composition-actions{justify-content:flex-start}.composition-panel article{padding:14px 0;border-bottom:1px solid var(--dew-card-flat-border)}.composition-panel h3,.composition-panel h4{margin:0 0 7px}.composition-panel p{font-size:13px;color:var(--dew-text-muted)}</style>
